import { newtabDB } from '@core/storage/newtab-storage';
import { putStamped, softDeleteNewTab } from '@core/storage/newtab-soft-delete';
import type { QuickLink } from '@core/types/newtab.types';
import { generateId } from '@core/utils/uuid';
import { guardAction, trackAction } from '@core/services/limits/limit-guard';

const db = newtabDB;

const STORE = 'quickLinks';

export async function getQuickLinks(): Promise<QuickLink[]> {
  const links = await db.getAll<QuickLink>(STORE);
  // Auto-generated links came from the removed "Frequently visited" (topSites) feature.
  return links
    .filter((l) => !l.isAutoGenerated && !l.deletedAt)
    .sort((a, b) => a.position - b.position);
}

export async function saveQuickLink(
  link: Omit<QuickLink, 'id'>,
): Promise<QuickLink> {
  await guardAction();
  const record: QuickLink = { ...link, id: generateId() };
  await putStamped(STORE, record);
  void trackAction();
  return record;
}

export async function updateQuickLink(
  id: string,
  updates: Partial<Omit<QuickLink, 'id'>>,
): Promise<void> {
  await guardAction();
  const existing = await db.get<QuickLink>(STORE, id);
  if (!existing) return;
  await putStamped(STORE, { ...existing, ...updates });
  void trackAction();
}

export async function deleteQuickLink(id: string): Promise<void> {
  await guardAction();
  await softDeleteNewTab(STORE, id);
  void trackAction();
}

export async function reorderQuickLinks(orderedIds: string[]): Promise<void> {
  const all = await db.getAll<QuickLink>(STORE);
  const map = new Map(all.map((l) => [l.id, l]));
  await Promise.all(
    orderedIds.map((id, index) => {
      const link = map.get(id);
      if (link) return putStamped(STORE, { ...link, position: index });
      return Promise.resolve();
    }),
  );
}
